use ql_benches::{format_markdown_table, run_all_benchmarks};
use std::fs;
use std::path::PathBuf;

fn main() {
    let rows = run_all_benchmarks(5);
    let report = format_markdown_table(&rows);
    println!("{report}");
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("BENCHMARK_RESULTS.md");
    let document = format!(
        "# ql-rs Quantitative Performance Benchmarks\n\nGenerated by `cargo +nightly bench -p ql-benches`.\n\n{report}"
    );
    let write_report = std::env::args().skip(1).any(|arg| arg == "--write-report")
        || std::env::var("QL_WRITE_BENCH_REPORT").is_ok();
    if write_report {
        fs::write(path, &document).expect("write benchmark report");
        let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../knowledge_base/08_BENCHMARK_RESULTS.md");
        if let Some(parent) = root.parent() {
            let _ = fs::create_dir_all(parent);
        }
        fs::write(root, document).expect("write benchmark knowledge report");
    }
}
